import sys,json,copy,hashlib,struct,re,argparse
from pathlib import Path
parser=argparse.ArgumentParser(description="Assemble native game material-library graphs from offline Shader inputs.")
parser.add_argument('--game-resources',type=Path,required=True)
parser.add_argument('--program-dir',type=Path,required=True)
parser.add_argument('--output',type=Path,required=True)
parser.add_argument('--unitypy',type=Path)
args=parser.parse_args()
if args.unitypy:sys.path.insert(0,str(args.unitypy))
import UnityPy
root=Path(__file__).resolve().parents[2];out=args.output.resolve();out.mkdir(parents=True,exist_ok=True)
game=UnityPy.load(str(args.game_resources))
layouts={}
for name,source,mid in [('WorldLayeredPbr',17,117),('BoneDecal',18,108)]:
 env=UnityPy.load(str(Path(__file__).with_name('NativeGraphSeed.bundle')))
 objs=list(env.objects); mat=next(o for o in objs if o.type.name=='Material'); graph=next(o for o in objs if o.type.name=='MonoBehaviour'); shader=next(o for o in objs if o.type.name=='Shader'); ab=next(o for o in objs if o.type.name=='AssetBundle'); script=next(o for o in objs if o.type.name=='MonoScript')
 program=UnityPy.load(str(args.program_dir/f'{name}.bundle')); actual=next(o for o in program.objects if o.type.name=='Shader');shader.serialized_type.node=actual.serialized_type.node;shader.set_raw_data(actual.get_raw_data())
 material=next(o for o in game.objects if o.path_id==mid).read_typetree(mat.serialized_type.node)
 nativegraph=next(o for o in game.objects if o.path_id==124190).read_typetree(graph.serialized_type.node)
 desc=copy.deepcopy(next(d for d in nativegraph['m_MaterialLibrary']['m_Materials'] if d['m_Hash']==source))
 assert all(v['m_Texture']['m_PathID']==0 for k,v in material['m_SavedProperties']['m_TexEnvs'])
 sourceMat=copy.deepcopy(material)
 material['m_Shader']={'m_FileID':0,'m_PathID':shader.path_id}
 material['m_SavedProperties']['m_Colors'].append(('colossal_BoneParameters',dict(r=0.,g=0.,b=0.,a=0.)))
 mat.save_typetree(material)
 g=graph.read_typetree(); desc['m_Material']={'m_FileID':0,'m_PathID':mat.path_id};g['m_MaterialLibrary']['m_Materials']=[desc];graph.save_typetree(g)
 for o in objs:
  if o.type.name=='Material' and o.path_id!=mat.path_id:del o.assets_file.objects[o.path_id]
 a=ab.read_typetree(); ident=hashlib.sha256(name.encode()).hexdigest()[:32];a['m_Name']=ident;a['m_AssetBundleName']=ident
 a['m_PreloadTable']=[{'m_FileID':0,'m_PathID':o.path_id} for o in [shader,script,mat,graph]]
 a['m_Container']=[('assets/nativegraph.asset',dict(preloadIndex=0,preloadSize=4,asset={'m_FileID':0,'m_PathID':graph.path_id}))];ab.save_typetree(a)
 bundle=next(iter(env.files.values())); oldkey=next(k for k,v in bundle.files.items() if hasattr(v,'objects'));sf=bundle.files.pop(oldkey); bundle.files['CAB-'+ident]=sf
 data=bundle.save(packer='none'); (out/f'{name}.bundle').write_bytes(data)
 # Discover precise native scalar offsets by same-size alternate serializations.
 def delta(obj,tree,key,value):
  before=copy.deepcopy(tree);tree[key]=value;obj.save_typetree(tree);changed=bundle.save(packer='none');obj.save_typetree(before);tree[key]=before[key]
  ix=[i for i,(x,y) in enumerate(zip(data,changed)) if x!=y];assert len(data)==len(changed);return min(ix)
 qoff=delta(mat,material,'m_CustomRenderQueue',0x12345678)
 g2=copy.deepcopy(g);g2['m_MaterialLibrary']['m_Materials'][0]['m_Hash']=0x12345678;graph.save_typetree(g2);changed=bundle.save(packer='none');graph.save_typetree(g)
 hoff=min(i for i,(x,y) in enumerate(zip(data,changed)) if x!=y)
 offsets=[m.start() for m in re.finditer(ident.encode(),data)];assert len(offsets)>=3
 layouts[source]=dict(program=name,hashOffset=hoff,queueOffset=qoff,defaultQueue=sourceMat['m_CustomRenderQueue'],identityOffsets=offsets,sha256=hashlib.sha256(data).hexdigest(),bytes=len(data),textures=len(sourceMat['m_SavedProperties']['m_TexEnvs']),floats=len(sourceMat['m_SavedProperties']['m_Floats']),colors=len(sourceMat['m_SavedProperties']['m_Colors']),description=desc)
 cold=UnityPy.load(data);assert next(o for o in cold.objects if o.type.name=='Shader').get_raw_data()==actual.get_raw_data()
 (out/f'{name}-source-material.json').write_text(json.dumps(sourceMat,indent=2))
(out/'layout.json').write_text(json.dumps(layouts,indent=2));print(json.dumps(layouts,indent=2))

lines=['// Generated by BuildNativeMaterialGraph.py; offsets address native UnityFS fields.','namespace BridgeBuilder.Runtime;','internal static class BridgeNativeProgramLayout','{']
for method,key in [('HashOffset','hashOffset'),('QueueOffset','queueOffset'),('DefaultQueue','defaultQueue')]:lines.append(f'    internal static int {method}(int sourceTemplate) => sourceTemplate == 17 ? {layouts[17][key]} : {layouts[18][key]};')
lines.append('    internal static int[] IdentityOffsets(int sourceTemplate) => sourceTemplate == 17')
lines.append('        ? new[] { '+', '.join(map(str,layouts[17]['identityOffsets']))+' }')
lines.append('        : new[] { '+', '.join(map(str,layouts[18]['identityOffsets']))+' };')
lines.append('}');(out/'BridgeNativeProgramLayout.g.cs').write_text('\n'.join(lines)+'\n')

for source,entry in layouts.items():
 name=entry['program'];upstream=json.loads((args.program_dir/(name+'.manifest.json')).read_text())
 sources=dict(upstream['sources'])
 for file in [Path(__file__),Path(__file__).with_name('NativeGraphSeed.bundle')]:sources[file.relative_to(root).as_posix()]=hashlib.sha256(file.read_bytes()).hexdigest()
 manifest=dict(schema=2,program=name,producer=Path(__file__).name,producerSha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),packageBytes=entry['bytes'],packageSha256=entry['sha256'],format='UnityFS',sources=sources,nativeInputs=dict(upstreamShaderBundle=hashlib.sha256((args.program_dir/(name+'.bundle')).read_bytes()).hexdigest(),gameResources=hashlib.sha256(args.game_resources.read_bytes()).hexdigest(),upstream=upstream.get('nativeInputs',{})),sourceTemplate=source)
 (out/(name+'.manifest.json')).write_text(json.dumps(manifest,indent=2)+'\n')
